import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"太空能源与月球工业化","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/space-energy/index.md","filePath":"topics/space-energy/index.md"}'),i={name:"topics/space-energy/index.md"};function n(s,t,l,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="太空能源与月球工业化" tabindex="-1">太空能源与月球工业化 <a class="header-anchor" href="#太空能源与月球工业化" aria-label="Permalink to &quot;太空能源与月球工业化&quot;">​</a></h1><blockquote><p>天基发电、无线传能、月球就地取材 —— 一条从 1968 年讲到 2026 年的技术史，以及它被反复&quot;重新发现&quot;的原因。</p><p>建立日期：2026-10-24（源自王钦文 × 马兆远访谈的收尾构想核实）</p></blockquote><hr><h2 id="这个主题关心什么" tabindex="-1">这个主题关心什么 <a class="header-anchor" href="#这个主题关心什么" aria-label="Permalink to &quot;这个主题关心什么&quot;">​</a></h2><p>把太阳搬到天上用，再把电送回地面 —— 这个想法比大多数人以为的古老得多。本主题记录：</p><ol><li><strong>技术源流</strong>：谁在什么时候提出了什么，各自的硬数据与硬上限</li><li><strong>路线之争</strong>：地球同步轨道（GEO）vs 月球表面 vs 其他轨道</li><li><strong>瓶颈的量化</strong>：为什么这件事到现在还没成 —— 用乘积链而不是单点指标看</li><li><strong>表述的失真</strong>：一个 1979 年算过账的方案，为什么在 2026 年还能被当成&quot;新构想&quot;讲</li></ol><hr><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><h3 id="月球工业伴星与空间太阳能电站-⭐-主线" tabindex="-1"><a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html">月球工业伴星与空间太阳能电站</a> ⭐ 主线 <a class="header-anchor" href="#月球工业伴星与空间太阳能电站-⭐-主线" aria-label="Permalink to &quot;[月球工业伴星与空间太阳能电站](lunar-industrial-satellite.md) ⭐ 主线&quot;">​</a></h3><p>一次完整核实：王钦文 × 马兆远访谈的&quot;将月球打造为地球的工业伴星&quot;构想。</p><ul><li>★ <strong>核心发现</strong>：该构想并非新提出 —— <strong>1979-04-30 NASA 报告《Lunar Resources Utilization for Space Construction》（合同 NAS9-15560）已量化论证&quot;30 座 × 10 GW&quot;规模下月球材料比地球材料更便宜</strong>；源头可追到 O&#39;Neill《The High Frontier》(1976)</li><li>空间太阳能电站 60 年时间线：Glaser 1968（<em>Science</em>）→ 专利 3,781,647 (1973) → NASA CR-2357 (1974) → JPL 30 kW/1 mile/9.6% (1975) → 1979 月球报告 → SELENE 1991–93 → JAXA 1.8 kW/50 m (2015) → Caltech MAPLE 首次太空传能 (2023-03-03, 地面仅收 &lt;0.1 µW) → 中国逐日工程</li><li>★ <strong>中国真实路线是 GEO，不是月球</strong>：逐日工程（西安电子科技大学段宝岩院士团队牵头，2018-12-23 西安启动，2022-06-05 全链路地面验证系统验收）；<strong>2026-05-18 新华社</strong>：百米级 DC-DC 效率 20.8%、输出 1180 W、波束收集效率 88.0%</li><li>规模硬账：4 GW 电站按 20 kg/kW ≈ <strong>80,000 公吨</strong>，需把 kg/kW 压到 1 量级</li><li>瓶颈排序 + 最新进展可信度分级 + 时间表判断</li></ul><hr><h2 id="关键判据-本主题沉淀的方法" tabindex="-1">关键判据（本主题沉淀的方法） <a class="header-anchor" href="#关键判据-本主题沉淀的方法" aria-label="Permalink to &quot;关键判据（本主题沉淀的方法）&quot;">​</a></h2><h3 id="_1-效率是乘出来的-不是加出来的" tabindex="-1">1. 效率是乘出来的，不是加出来的 <a class="header-anchor" href="#_1-效率是乘出来的-不是加出来的" aria-label="Permalink to &quot;1. 效率是乘出来的，不是加出来的&quot;">​</a></h3><p>&quot;聚光 × 光电转换 × 微波转换 × 波束收集 × 整流 × DC-DC&quot; —— 六个环节各 90%，整体只剩 53%。 看任何天基能源宣称，先问：<strong>它报的是单环节效率，还是全链路效率？</strong></p><h3 id="_2-构想-方案-地面验证-上天" tabindex="-1">2. 构想 ≠ 方案 ≠ 地面验证 ≠ 上天 <a class="header-anchor" href="#_2-构想-方案-地面验证-上天" aria-label="Permalink to &quot;2. 构想 ≠ 方案 ≠ 地面验证 ≠ 上天&quot;">​</a></h3><p>四步的<strong>证据硬度</strong>逐级跃迁，表述里最容易含混：</p><ul><li><strong>构想</strong>（1979 年报告的月球方案、2026 年月球激光塔提案）</li><li><strong>方案</strong>（欧米伽 OMEGA 设计）</li><li><strong>地面验证</strong>（逐日工程 2022-06 全链路系统验收、2026 百米级 1180 W）</li><li><strong>在轨运行</strong>（<strong>至今没有任何一座有工程意义的空间太阳能电站在轨运行</strong>）</li></ul><p>⚠️ 「地面验证系统通过验收」被读成「电站上天」，是这个领域的头号口径漂移。</p><h3 id="_3-老的-更便宜-结论可能建立在已破产的假设上" tabindex="-1">3. 老的&quot;更便宜&quot;结论可能建立在已破产的假设上 <a class="header-anchor" href="#_3-老的-更便宜-结论可能建立在已破产的假设上" aria-label="Permalink to &quot;3. 老的&quot;更便宜&quot;结论可能建立在已破产的假设上&quot;">​</a></h3><p>1979 年&quot;月球材料更便宜&quot;依赖 1970 年代 NASA 对航天飞机发射成本的乐观估算；1980 年该估算暴露失准后路线被迫改写。 → <strong>重提旧构想时，第一步是重算它当年的假设，而不是当成新展望。</strong></p><hr><h2 id="跨主题连接" tabindex="-1">跨主题连接 <a class="header-anchor" href="#跨主题连接" aria-label="Permalink to &quot;跨主题连接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>连接对象</th><th>连接点</th></tr></thead><tbody><tr><td><span class="uncollected-link" title="此关联资料尚未收录到阅读站"><code>../philosophy/russell-in-praise-of-idleness.md</code></span></td><td>技术乐观论的另一面：技术能否改善人类处境取决于<strong>分配</strong>，不是技术本身</td></tr><tr><td><a href="/zhishiku-reading/topics/energysim/"><code>../energysim/</code></a></td><td>全链路效率的乘积结构 = PyPSA 里 Converter 效率建模的同一个问题</td></tr><tr><td><a href="/zhishiku-reading/topics/real-estate/"><code>../real-estate/</code></a></td><td>&quot;规划 ≠ 开工 ≠ 交付&quot; = 本主题&quot;构想 ≠ 进展&quot;的证据硬度阶梯</td></tr><tr><td><a href="/zhishiku-reading/topics/wind-energy/"><code>../wind-energy/</code></a></td><td>极端环境下&quot;现场可靠性优先于纸面效率&quot;（月尘、14 天月夜 ↔ 风电现场工况）</td></tr><tr><td><a href="/zhishiku-reading/topics/science-news/"><code>../science-news/index.md</code></a></td><td>本篇是&quot;时间错位&quot;型失真的代表性案例</td></tr></tbody></table>',24)])])}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
